using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Object=UnityEngine.Object;
namespace YamyamCoding.PortalTraversal.Editor {
 public static class Capture {
 const string Root="Assets/VideoScenes/portal-traversal-shorts-20261025";const int W=1080;
 [Serializable]public class Section{public string id,kind;public int startFrame,endFrame;public float start,end;}
 [Serializable]public class Timeline{public int frames;public float durationSeconds;public Section[]sections;}
 [Serializable]public class Job{public string topic,output,mode,timeline;public string[]sections;}
 [Serializable]public class Record{public int frame;public string section;public float elapsed,speedIn,speedOut,distance;public bool crossed;public Vector3 body,focus,copy,velocity;}
 [Serializable]public class Report{public string topic,driver;public int width=1080,height=1080,frames;public List<Record>records=new List<Record>();public string[]scenes;public float maximumSpeedError;}
 static Job job;static PortalDemo d;static Camera cam,player,portalCam;static RenderTexture rt,playerRT,viewRT;static Texture2D image;static Material lineMat,leftView,rightView;static Transform left,right;static Color yellow=new Color(1,.82f,.35f),teal=new Color(.45f,.84f,.80f),red=new Color(.95f,.48f,.44f),dark=new Color(.055f,.085f,.10f);
 static Material Mat(string n,Color c){string p=Root+"/Materials/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Yamyam/PortalTraversalSurface"));AssetDatabase.CreateAsset(m,p);}m.color=c;m.SetVector("_ClipPlane",new Vector4(0,0,0,1));return m;}
 static GameObject Part(string n,PrimitiveType t,Vector3 p,Vector3 s,Material m){var g=GameObject.CreatePrimitive(t);g.name=n;g.transform.position=p;g.transform.localScale=s;Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=m;return g;}
 static LineRenderer Line(string n,Color c,float width=.04f){var g=new GameObject(n);g.layer=8;var l=g.AddComponent<LineRenderer>();l.sharedMaterial=lineMat;l.startWidth=l.endWidth=width;l.startColor=l.endColor=c;l.numCapVertices=4;return l;}
 static void Floor(){Part("Room floor",PrimitiveType.Cube,new Vector3(0,-.13f,0),new Vector3(14,.2f,10),Mat("Floor",dark));for(int i=-6;i<=6;i++){var l=Line("1m floor grid",teal*.25f,.01f);l.positionCount=2;l.SetPositions(new[]{new Vector3(i,.0f,-4),new Vector3(i,0,4)});}for(int i=-4;i<=4;i++){var l=Line("1m floor grid",teal*.25f,.01f);l.positionCount=2;l.SetPositions(new[]{new Vector3(-6,0,i),new Vector3(6,0,i)});}}
 static Transform Portal(string name,Vector3 p,Quaternion q,Color c,bool window){var g=new GameObject(name).transform;g.position=p;g.rotation=q;var m=Mat(name+"Frame",c);for(int i=-1;i<=1;i+=2){var side=Part(name+" jamb",PrimitiveType.Cube,Vector3.zero,new Vector3(.15f,3,.18f),m);side.transform.SetParent(g,false);side.transform.localPosition=new Vector3(i*1.0f,0,0);var cross=Part(name+" crossbar",PrimitiveType.Cube,Vector3.zero,new Vector3(2.15f,.15f,.18f),m);cross.transform.SetParent(g,false);cross.transform.localPosition=new Vector3(0,i*1.5f,0);}
 if(window){var quad=Part(name+" view",PrimitiveType.Quad,Vector3.zero,new Vector3(1.95f,2.9f,1),m);quad.transform.SetParent(g,false);quad.transform.localPosition=Vector3.zero;string path=Root+"/Materials/"+name+"View.mat";var v=AssetDatabase.LoadAssetAtPath<Material>(path);if(!v){v=new Material(Shader.Find("Yamyam/PortalTraversalView"));AssetDatabase.CreateAsset(v,path);}quad.GetComponent<Renderer>().sharedMaterial=v;if(name=="Entrance")leftView=v;else rightView=v;}
 return g;}
 static Transform Knight(string name,out Material material){const string asset="Assets/ThirdParty/KayKitAdventurers/";var src=AssetDatabase.LoadAssetAtPath<GameObject>(asset+"Knight.fbx");var g=(GameObject)PrefabUtility.InstantiatePrefab(src);g.name=name;foreach(var a in g.GetComponentsInChildren<Animator>())a.enabled=false;material=Mat(name,Color.white);material.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(asset+"knight_texture.png");foreach(var r in g.GetComponentsInChildren<Renderer>()){r.sharedMaterial=material;if(r is SkinnedMeshRenderer sk)sk.updateWhenOffscreen=true;}foreach(var t in g.GetComponentsInChildren<Transform>()){t.gameObject.layer=9;if(t.name.Contains("Sword")||t.name.Contains("Shield"))t.gameObject.SetActive(false);}var clip=AssetDatabase.LoadAllAssetsAtPath(asset+"Knight.fbx").OfType<AnimationClip>().First(c=>c.name=="Idle");clip.SampleAnimation(g,.7f);g.transform.localScale=Vector3.one*.72f;return g.transform;}
 static Camera Camera(string name){var c=new GameObject(name).AddComponent<Camera>();c.enabled=false;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=Color.black;c.nearClipPlane=.025f;c.farClipPlane=60;c.aspect=1;c.allowHDR=false;return c;}
 static void Build(){Directory.CreateDirectory(Root+"/Materials");Directory.CreateDirectory(Root+"/Scenes/"+job.topic);AssetDatabase.Refresh();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);GraphicsSettings.defaultRenderPipeline=null;QualitySettings.renderPipeline=null;QualitySettings.antiAliasing=1;PlayerSettings.colorSpace=ColorSpace.Linear;
 d=new GameObject("Editable portal lesson").AddComponent<PortalDemo>();d.topic=job.topic;cam=Camera("Observer — synchronized world view");player=Camera("Player — actual transferred camera");portalCam=Camera("Portal view camera");d.observer=cam;d.player=player;player.cullingMask=~((1<<8)|(1<<9));player.fieldOfView=65;
 lineMat=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/Lines.mat");if(!lineMat){lineMat=new Material(Shader.Find("Sprites/Default"));AssetDatabase.CreateAsset(lineMat,Root+"/Materials/Lines.mat");}Floor();
 if(job.topic=="momentum"){
  d.entry=Portal("Entrance",new Vector3(-2,0,0),Quaternion.LookRotation(Vector3.up,Vector3.forward),teal,false);d.exit=Portal("Exit",new Vector3(1,2.6f,0),Quaternion.LookRotation(Vector3.right,Vector3.up),yellow,false);
  d.body=Part("Incoming physical object",PrimitiveType.Sphere,Vector3.zero,Vector3.one*.65f,Mat("Ball",Color.white)).transform;d.copy=Part("Transformed comparison object",PrimitiveType.Sphere,Vector3.zero,Vector3.one*.65f,Mat("CompareBall",yellow)).transform;
  var wall=Mat("Wall",new Color(.12f,.17f,.19f));for(int side=-1;side<=1;side+=2)Part("Wall beside opening",PrimitiveType.Cube,new Vector3(.91f,2.5f,side*1.8f),new Vector3(.15f,5,1.5f),wall);
  Part("Wall below opening",PrimitiveType.Cube,new Vector3(.91f,.5f,0),new Vector3(.15f,1,2.1f),wall);Part("Wall above opening",PrimitiveType.Cube,new Vector3(.91f,4.65f,0),new Vector3(.15f,.7f,2.1f),wall);
 }else{
  d.entry=Portal("Entrance",new Vector3(-2.8f,1.5f,2.5f),Quaternion.Euler(0,180,0),teal,true);d.exit=Portal("Exit",new Vector3(2.8f,1.5f,2.5f),Quaternion.Euler(0,180,0),yellow,true);left=d.entry;right=d.exit;
  d.body=Knight("One physical player",out d.bodyMaterial);d.copy=Knight("Visual-only copy — no collider",out d.copyMaterial);var clips=AssetDatabase.LoadAllAssetsAtPath("Assets/ThirdParty/KayKitAdventurers/Knight.fbx").OfType<AnimationClip>().ToArray();d.walkClip=clips.FirstOrDefault(c=>c.name.ToLower().Contains("walk"))??clips.First(c=>c.name=="Idle");Debug.Log("PORTAL_ANIMATION "+d.walkClip.name);
  Part("Middle wall",PrimitiveType.Cube,new Vector3(0,1.5f,2.65f),new Vector3(3.4f,3,.2f),Mat("Wall",new Color(.12f,.17f,.19f)));
  Part("Left room landmark",PrimitiveType.Cylinder,new Vector3(-4.4f,.4f,-1),new Vector3(.8f,.4f,.8f),Mat("LandmarkA",teal));Part("Right room landmark",PrimitiveType.Cube,new Vector3(4.4f,.45f,-1),Vector3.one*.9f,Mat("LandmarkB",yellow));
  Part("Far room wall",PrimitiveType.Cube,new Vector3(0,1.6f,-4),new Vector3(14,3.2f,.15f),Mat("FarWall",new Color(.16f,.22f,.26f)));for(int i=-5;i<=5;i+=2)Part("Wall orientation stripe",PrimitiveType.Cube,new Vector3(i,1.4f,-3.91f),new Vector3(.12f,2.4f,.04f),Mat("Stripe",new Color(.3f,.40f,.43f)));
  foreach(var grid in Object.FindObjectsByType<LineRenderer>(FindObjectsSortMode.None).Where(x=>x.name=="1m floor grid"))grid.gameObject.layer=0;
 }
 d.incoming=Line("Entrance direction",teal,.055f);d.outgoing=Line("Exit direction",yellow,.055f);rt=new RenderTexture(W,W,24);rt.Create();playerRT=new RenderTexture(W,W,24);playerRT.Create();viewRT=new RenderTexture(W,W,24);viewRT.Create();cam.targetTexture=rt;player.targetTexture=playerRT;portalCam.targetTexture=viewRT;image=new Texture2D(W,W,TextureFormat.RGB24,false);
 foreach(var s in job.sections.Where(s=>!s.StartsWith("game"))){d.section=s;d.elapsed=2;d.Apply();cam.enabled=true;EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),Root+"/Scenes/"+job.topic+"/"+s+".unity");cam.enabled=false;}AssetDatabase.SaveAssets();
 }
 static Vector3 Screen(Vector3 p){var v=cam.WorldToScreenPoint(p);return new Vector3(v.x,W-v.y,v.z);}
 static void Views(){if(job.topic=="momentum")return;leftView.mainTexture=rightView.mainTexture=Texture2D.blackTexture;portalCam.CopyFrom(player);portalCam.enabled=false;portalCam.targetTexture=viewRT;portalCam.transform.position=d.MapPoint(player.transform.position);portalCam.transform.rotation=d.MapRotation(player.transform.rotation);portalCam.ResetProjectionMatrix();
 var surfaces=new[]{left.Find("Entrance view").gameObject,right.Find("Exit view").gameObject};foreach(var s in surfaces)s.SetActive(false);var worldTo=portalCam.worldToCameraMatrix;Vector3 pp=worldTo.MultiplyPoint(right.position+right.forward*.04f),nn=worldTo.MultiplyVector(right.forward).normalized;portalCam.projectionMatrix=portalCam.CalculateObliqueMatrix(new Vector4(nn.x,nn.y,nn.z,-Vector3.Dot(pp,nn)));portalCam.Render();foreach(var s in surfaces)s.SetActive(true);leftView.mainTexture=viewRT;}
 static void Picture(string path,Camera camera){GameObject[] surfaces=null;if(job.topic!="momentum"&&camera==cam){surfaces=new[]{left.Find("Entrance view").gameObject,right.Find("Exit view").gameObject};foreach(var s in surfaces)s.SetActive(false);}camera.Render();if(surfaces!=null)foreach(var s in surfaces)s.SetActive(true);RenderTexture.active=camera.targetTexture;image.ReadPixels(new Rect(0,0,W,W),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToJPG(93));RenderTexture.active=null;}
 public static void Run(){try{var args=Environment.GetCommandLineArgs();job=JsonUtility.FromJson<Job>(File.ReadAllText(args[Array.IndexOf(args,"-portalJob")+1]));Directory.CreateDirectory(job.output);Build();var report=new Report{topic=job.topic,driver=SystemInfo.graphicsDeviceName};
 Action<int,string,float,float> frame=(f,s,e,duration)=>{d.section=s;d.elapsed=e;d.sectionDuration=duration;d.Apply();Views();report.records.Add(new Record{frame=f,section=s,elapsed=e,crossed=d.crossed,distance=d.signedDistance,speedIn=d.speed,speedOut=d.MapVector(Vector3.down*d.speed).magnitude,body=d.body.position,copy=d.copy.position,velocity=d.velocity,focus=Screen(d.body.position)});report.maximumSpeedError=Mathf.Max(report.maximumSpeedError,Mathf.Abs(d.speed-d.MapVector(Vector3.down*d.speed).magnitude));};
 if(job.mode.StartsWith("preview")){foreach(var s in job.sections.Where(s=>!s.StartsWith("game"))){foreach(float e in new[]{.5f,2.0f,4.5f}){frame(0,s,e,6);string name=s+"-"+e.ToString("0.0",System.Globalization.CultureInfo.InvariantCulture);Picture(Path.Combine(job.output,name+".jpg"),cam);if(job.topic!="momentum")Picture(Path.Combine(job.output,name+"-player.jpg"),player);}}}
 else{var time=JsonUtility.FromJson<Timeline>(File.ReadAllText(job.timeline));Directory.CreateDirectory(Path.Combine(job.output,"frames"));Directory.CreateDirectory(Path.Combine(job.output,"player"));for(int f=0;f<time.frames;f++){var s=time.sections.First(s=>f>=s.startFrame&&f<s.endFrame);frame(f,s.id,(f-s.startFrame)/60f,s.end-s.start);if(s.kind!="game"){Picture(Path.Combine(job.output,"frames",f.ToString("D5")+".jpg"),cam);if(job.topic!="momentum")Picture(Path.Combine(job.output,"player",f.ToString("D5")+".jpg"),player);}if(f%300==0)Debug.Log("PORTAL_FRAME "+f+"/"+time.frames);}}
 report.frames=report.records.Count;report.scenes=Directory.GetFiles(Root+"/Scenes/"+job.topic,"*.unity");File.WriteAllText(Path.Combine(job.output,"readback.json"),JsonUtility.ToJson(report,true));File.WriteAllText(Path.Combine(job.output,"success.json"),"{\"frames\":"+report.frames+",\"width\":1080,\"height\":1080}");EditorApplication.Exit(0);
 }catch(Exception ex){Debug.LogException(ex);EditorApplication.Exit(1);}}
 }
}
